use std::io
use std::collections::HashMap

fn main() {
    let mut accts: HashMap<string, int> = HashMap::new()
    let mut out: Vec<string> = Vec::new()
    loop {
        let r = io::read_line()
        let line = match r {
            Ok(s) => s,
            Err(_) => break,
        }
        if line.len() == 0 {
            break
        }
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0].clone()
        if cmd == "open" && parts.len() >= 3 {
            let name = parts[1].clone()
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                out.push("error: invalid amount")
            } else if accts.contains_key(name.as_str()) {
                out.push("error: duplicate account")
            } else {
                accts.insert(name, amt)
                out.push("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && parts.len() >= 3 {
            let name = parts[1].clone()
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                out.push("error: invalid amount")
            } else if !accts.contains_key(name.as_str()) {
                out.push("error: unknown account ${name}")
            } else {
                let bal: int = accts.get(name.as_str()).copied().unwrap_or(0)
                if cmd == "deposit" {
                    accts.insert(name, bal + amt)
                    out.push("ok")
                } else if amt > bal {
                    out.push("error: insufficient funds")
                } else {
                    accts.insert(name, bal - amt)
                    out.push("ok")
                }
            }
        } else if cmd == "transfer" && parts.len() >= 4 {
            let from = parts[1].clone()
            let to = parts[2].clone()
            let amt: int = parts[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                out.push("error: invalid amount")
            } else if !accts.contains_key(from.as_str()) {
                out.push("error: unknown account ${from}")
            } else if !accts.contains_key(to.as_str()) {
                out.push("error: unknown account ${to}")
            } else if from == to {
                out.push("error: same account")
            } else {
                let fb: int = accts.get(from.as_str()).copied().unwrap_or(0)
                let tb: int = accts.get(to.as_str()).copied().unwrap_or(0)
                if amt > fb {
                    out.push("error: insufficient funds")
                } else {
                    accts.insert(from, fb - amt)
                    accts.insert(to, tb + amt)
                    out.push("ok")
                }
            }
        } else if cmd == "balance" && parts.len() >= 2 {
            let name = parts[1].clone()
            if !accts.contains_key(name.as_str()) {
                out.push("error: unknown account ${name}")
            } else {
                let bal: int = accts.get(name.as_str()).copied().unwrap_or(0)
                out.push("${bal}")
            }
        }
    }
    let mut names: Vec<string> = Vec::new()
    for k in accts.keys() {
        names.push(k.clone())
    }
    names.sort()
    for n in names {
        let b: int = accts.get(n.as_str()).copied().unwrap_or(0)
        out.push("${n} ${b}")
    }
    for l in out {
        println("${l}")
    }
}

